package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

func isvalid(x int) int {
	if x < 1 || x > 1000000000 {
		return 0
	}
	s := fmt.Sprint(x)
	set := make(map[rune]struct{})
	for _, ch := range s {
		set[ch] = struct{}{}
	}
	if len(set) <= 2 {
		return 1
	}
	return 0
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(in, &n)

	curr := make(map[int]struct{})
	for i := 1; i < 100; i++ {
		curr[i] = struct{}{}
	}

	cnt := 0
	for cnt <= 100000 {
		curr1 := make(map[int]struct{})
		for i := range curr {
			for j := 0; j < 10; j++ {
				val := i*10 + j
				if isvalid(val) == 1 {
					if _, exists := curr1[val]; !exists {
						curr1[val] = struct{}{}
						cnt++
					}
				}
			}
		}
		for k := range curr1 {
			curr[k] = struct{}{}
		}
	}

	currSlice := make([]int, 0, len(curr))
	for k := range curr {
		currSlice = append(currSlice, k)
	}
	sort.Ints(currSlice)

	ans := 0
	for _, v := range currSlice {
		if v >= 1 && v <= n {
			ans++
		} else if v > n {
			break
		}
	}
	fmt.Println(ans)
}

